/// <summary>
/// Extension of <c>GUPDiscountClaim</c> datasource <c>METVendorClaimTable</c>.
/// </summary>
[ExtensionOf(formDataSourceStr(GUPDiscountClaim, METVendorClaimTable))]
final class METGUPDiscountClaimFormVendorClaimTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Checks and returns if record is active.
/// </summary>
/// <returns>Record active.</returns>
public int active()
{
    METVendorClaimTable vendClaimTable;
    FormRun             formRun;
    boolean             vfdVarClaimEnable;
    int                 ret;

    formRun = this.formRun();
    vendClaimTable = this.cursor();

    ret = next active();

    vfdVarClaimEnable = (vendClaimTable.ClaimType == MetVendClaimType::VFDVariance);

    formRun.design().controlName(formControlStr(GUPDiscountClaim, METVFDVarVendClaimJournalProcess)).enabled(vfdVarClaimEnable);

    return ret;
}
